function [n, ht, hq] = st_history(ht, hq, hn, t, q)
%ST_HISTORY  Record the true attitude q at t into the history (its epochs ht and attitudes hq, the first hn held), keeping the
%   last 0.5 s. The history's length after.
%   ht: inout real[1][ST_HIST] (passed a plain number)
%   hq: inout real[1][4][ST_HIST] (passed a plain number)
%   hn: int (passed a whole number)
%   t: real[1] (passed a plain number)
%   q: real[1][4] (passed a plain number)
%   returns n: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    n = 0;
    n = hn;
    if (n == 64)
        for i = (1):((64) - 1)
            ht(((i - 1)) + 1) = ht((i) + 1);
            hq(((i - 1)) + 1, :) = (hq((i) + 1, :)).'.';
        end
        n = (n - 1);
    end
    ht((n) + 1) = t;
    hq((n) + 1, :) = q.';
    n = (n + 1);
    k = 0;
    going = true;
    for j = (0):((n) - 1)
        if (going && (ht((j) + 1) < (t - 0.5)))
            k = (j + 1);
        else
            going = false;
        end
    end
    if (k > 0)
        for m = (k):((n) - 1)
            ht(((m - k)) + 1) = ht((m) + 1);
            hq(((m - k)) + 1, :) = (hq((m) + 1, :)).'.';
        end
        n = (n - k);
    end
end
